import subprocess,re,json
d={}
for key,cmd in [("nginx",["sudo","-n","nginx","-T"]),("listen",["ss","-lntH","sport = :443"])]:
 try:
  p=subprocess.run(cmd,capture_output=True,text=True,timeout=15)
  if key=="nginx":
   lines=p.stdout.splitlines()
   items=[]; file=""
   for line in lines:
    m=re.match(r"^# configuration file ([^:]+):",line)
    if m:file=m.group(1)
    x=line.strip()
    if re.match(r"^(include|listen|server_name)\\s",x) and ("443" in x or "http" in x or "duckdns" in x or "include" in x):
     items.append({"file":file,"directive":x[:180]})
   d[key]={"rc":p.returncode,"vhosts":items[-140:],"stderr":p.stderr[-600:]}
  else:d[key]={"rc":p.returncode,"stdout":p.stdout[:600]}
 except Exception as e:d[key]={"error":type(e).__name__+":"+str(e)[:100]}
print(json.dumps(d))
